/**
 * CPUState - Core data structure for CPU simulation
 *
 * Represents the complete state of a pipelined RISC CPU including:
 * - 5 pipeline stages (IF, ID, EX, MEM, WB)
 * - 32 general-purpose registers (register $0 hardwired to zero)
 * - 256-word data memory
 * - Program counter and cycle counters
 * - Visualization metadata for animation framework
 *
 * This class is the foundational unit of the animation system.
 * Every animation frame is a complete, immutable CPUState snapshot.
 */
(function() {
  'use strict';

  class CPUState {
    constructor() {
      // Pipeline stages with stage-specific fields
      this.pipeline = {
        IF: {
          instruction: null,
          pc: 0,
          active: false
        },
        ID: {
          instruction: null,
          opcode: '',
          rs: 0,
          rt: 0,
          rd: 0,
          imm: 0,
          rsVal: 0,
          rtVal: 0,
          active: false
        },
        EX: {
          aluResult: 0,
          writeData: 0,
          writeReg: 0,
          zero: false,
          active: false
        },
        MEM: {
          memData: 0,
          writeData: 0,
          writeReg: 0,
          memRead: false,
          memWrite: false,
          active: false
        },
        WB: {
          writeData: 0,
          writeReg: 0,
          regWrite: false,
          active: false
        }
      };

      // Registers: 32 general-purpose registers (Uint32Array for 32-bit unsigned)
      // Register $0 is hardwired to zero
      this.registers = new Uint32Array(32);

      // Memory: 256-word data memory (1KB for demo purposes)
      this.memory = new Uint32Array(256);

      // Control state
      this.pc = 0;  // Program counter (word-aligned, increments by 4)
      this.cycleCount = 0;  // Total clock cycles executed
      this.instructionCount = 0;  // Total instructions completed (written back)

      // Visualization metadata (for Phase 10+ animation)
      this.changedRegisters = new Set();  // Which registers changed this cycle
      this.changedMemory = new Set();  // Which memory addresses changed this cycle
      this.activeStages = new Set();  // Which pipeline stages are active this cycle
      this.hazards = [];  // Active hazards (forward compatibility for Phase 12)
      this.stalls = [];  // Active stalls (forward compatibility for Phase 12)
    }

    /**
     * Creates a fresh CPUState with all defaults
     * @returns {CPUState} A new CPUState instance
     */
    static createInitial() {
      const state = new CPUState();
      // Explicitly ensure register $0 is zero
      state.registers[0] = 0;
      return state;
    }

    /**
     * Creates a deep copy of this state
     * Uses structuredClone for complete independence
     * @returns {CPUState} A deep copy of this state
     */
    clone() {
      // structuredClone handles typed arrays and Sets natively
      const cloned = structuredClone(this);

      // Restore prototype chain (structuredClone creates plain objects)
      Object.setPrototypeOf(cloned, CPUState.prototype);

      // structuredClone handles Sets correctly, but ensure they're Sets not arrays
      if (Array.isArray(cloned.changedRegisters)) {
        cloned.changedRegisters = new Set(cloned.changedRegisters);
      }
      if (Array.isArray(cloned.changedMemory)) {
        cloned.changedMemory = new Set(cloned.changedMemory);
      }
      if (Array.isArray(cloned.activeStages)) {
        cloned.activeStages = new Set(cloned.activeStages);
      }

      return cloned;
    }

    /**
     * Gets a register value
     * Register $0 always returns 0
     * @param {number} index - Register index (0-31)
     * @returns {number} Register value
     */
    getRegister(index) {
      if (index === 0) {
        return 0;  // Register $0 is hardwired to zero
      }
      return this.registers[index];
    }

    /**
     * Sets a register value
     * Register $0 writes are ignored (hardwired to zero)
     * @param {number} index - Register index (0-31)
     * @param {number} value - Value to set
     */
    setRegister(index, value) {
      if (index === 0) {
        return;  // Cannot write to register $0
      }

      // Track change only if value actually changed
      const oldValue = this.registers[index];
      if (oldValue !== value) {
        this.registers[index] = value >>> 0;  // Ensure 32-bit unsigned
        this.changedRegisters.add(index);
      }
    }

    /**
     * Gets a word from memory
     * @param {number} address - Byte address (must be word-aligned)
     * @returns {number} Memory value
     */
    getMemory(address) {
      const wordIndex = address >> 2;  // Convert byte address to word index
      return this.memory[wordIndex];
    }

    /**
     * Sets a word in memory
     * @param {number} address - Byte address (must be word-aligned)
     * @param {number} value - Value to set
     */
    setMemory(address, value) {
      const wordIndex = address >> 2;  // Convert byte address to word index

      // Track change only if value actually changed
      const oldValue = this.memory[wordIndex];
      if (oldValue !== value) {
        this.memory[wordIndex] = value >>> 0;  // Ensure 32-bit unsigned
        this.changedMemory.add(address);
      }
    }
  }

  // Export to global scope (no module bundler - vanilla JS)
  if (typeof window !== 'undefined') {
    window.CPUState = CPUState;
  } else if (typeof global !== 'undefined') {
    global.CPUState = CPUState;
  }
})();

/**
 * TimingController - Manages playback speed and delta-time calculation
 *
 * Provides framerate-independent animation timing with configurable speed multipliers.
 * Uses delta-time accumulation to prevent frame drift on variable refresh rate displays.
 *
 * Key features:
 * - Speed range: 0.25x (quarter speed) to 4x (quadruple speed)
 * - Base FPS: 2 (educational pace for CPU pipeline visualization)
 * - Delta-time tracking prevents drift on 60Hz/120Hz/144Hz monitors
 * - Named speed presets for UI convenience
 */

(function() {
  'use strict';

  class TimingController {
    constructor() {
      // Base frames per second for educational CPU simulation
      // 2 FPS = 500ms per frame at 1x speed (time to observe each pipeline state)
      this.baseFPS = 2;

      // Current speed multiplier
      this.speed = 1.0;

      // Speed constraints
      this.minSpeed = 0.25;  // Quarter speed for detailed observation
      this.maxSpeed = 4.0;   // 4x speed for rapid demonstration

      // Named speed presets for UI
      this.speedPresets = {
        slow: 0.5,
        normal: 1.0,
        fast: 2.0,
        fastest: 4.0
      };

      // Timestamp tracking for delta-time calculation
      this.lastFrameTime = null;
    }

    /**
     * Set playback speed with clamping to valid range
     * @param {number} multiplier - Speed multiplier (will be clamped to [minSpeed, maxSpeed])
     * @returns {number} - Actual speed set (after clamping)
     */
    setSpeed(multiplier) {
      // Clamp to valid range
      this.speed = Math.max(this.minSpeed, Math.min(this.maxSpeed, multiplier));
      return this.speed;
    }

    /**
     * Calculate frame interval in milliseconds based on current speed
     * @returns {number} - Milliseconds between frames
     *
     * Examples:
     * - baseFPS=2, speed=1.0: 500ms (1000 / 2 / 1.0)
     * - baseFPS=2, speed=2.0: 250ms (1000 / 2 / 2.0)
     * - baseFPS=2, speed=0.5: 1000ms (1000 / 2 / 0.5)
     */
    getFrameInterval() {
      return (1000 / this.baseFPS) / this.speed;
    }

    /**
     * Check if enough time has passed to advance to next frame
     * Uses delta-time accumulation to prevent drift
     *
     * @param {number} currentTime - Current timestamp from performance.now() or rAF
     * @returns {boolean} - True if frame should advance
     */
    shouldAdvanceFrame(currentTime) {
      // Initialize on first call
      if (this.lastFrameTime === null) {
        this.lastFrameTime = currentTime;
        return false;
      }

      const deltaTime = currentTime - this.lastFrameTime;
      const frameInterval = this.getFrameInterval();

      // Check if enough time has passed
      if (deltaTime >= frameInterval) {
        // Update lastFrameTime with leftover accumulation to prevent drift
        // If deltaTime=520ms and frameInterval=500ms, carry forward 20ms
        this.lastFrameTime = currentTime - (deltaTime % frameInterval);
        return true;
      }

      return false;
    }

    /**
     * Reset timing state - call when starting or resuming playback
     */
    reset() {
      this.lastFrameTime = performance.now();
    }

    /**
     * Get human-readable speed label
     * @returns {string} - Speed label like "1x", "0.5x", "2x", "4x"
     */
    getSpeedLabel() {
      // Format with 'x' suffix, show decimals only if not whole number
      const speedValue = this.speed % 1 === 0 ? this.speed.toString() : this.speed.toFixed(2);
      return `${speedValue}x`;
    }

    /**
     * Apply a named speed preset
     * @param {string} presetName - One of: slow, normal, fast, fastest
     * @returns {boolean} - True if preset was applied, false if name invalid
     */
    applyPreset(presetName) {
      if (this.speedPresets.hasOwnProperty(presetName)) {
        this.setSpeed(this.speedPresets[presetName]);
        return true;
      }
      return false;
    }
  }

  // Export to window
  window.TimingController = TimingController;
})();

