/**
 * AnimationEngine - Frame-based animation playback controller
 *
 * Generic animation engine that manages an array of frame objects and provides:
 * - Navigation: stepForward, stepBackward, jumpToFrame
 * - Playback: play, pause, reset with requestAnimationFrame
 * - Speed control: via TimingController (0.25x to 4x)
 * - Events: CustomEvent 'cpu:framechange' on every frame change
 * - Visibility handling: auto-pause when tab hidden
 *
 * Design: Decoupled from CPU state - works with any array of frame objects.
 * This allows independent testing and potential reuse for other animations.
 */

(function() {
  'use strict';

  class AnimationEngine {
    constructor() {
      // Frame data and state
      this.frames = [];
      this.currentFrame = 0;
      this.isPlaying = false;

      // Timing controller for speed-adjusted playback
      this.timing = new window.TimingController();

      // RequestAnimationFrame tracking
      this.rafId = null;

      // Optional callback (alternative to events)
      this.onFrameChange = null;

      // Track visibility-based pausing
      this._pausedByVisibility = false;

      // Set up visibility change handler
      this._setupVisibilityHandler();
    }

    /**
     * Set up document visibility change handler
     * Prevents requestAnimationFrame throttling when tab is hidden
     */
    _setupVisibilityHandler() {
      document.addEventListener('visibilitychange', () => {
        if (document.hidden) {
          // Tab became hidden - pause if playing
          if (this.isPlaying) {
            this.pause();
            this._pausedByVisibility = true;
          }
        } else {
          // Tab became visible - resume if was auto-paused
          if (this._pausedByVisibility) {
            this.play();
            this._pausedByVisibility = false;
          }
        }
      });
    }

    // ========== FRAME LOADING ==========

    /**
     * Load frame array for playback
     * @param {Array} framesArray - Array of frame objects (any structure)
     */
    loadFrames(framesArray) {
      // Validate input
      if (!Array.isArray(framesArray)) {
        framesArray = [];
      }

      // Pause playback and reset position
      this.pause();
      this.frames = framesArray;
      this.currentFrame = 0;

      // Dispatch frame change event
      this._dispatchFrameChange();
    }

    // ========== NAVIGATION METHODS ==========

    /**
     * Advance to next frame
     * @returns {boolean} - True if moved, false if already at end
     */
    stepForward() {
      if (this.currentFrame < this.frames.length - 1) {
        this.currentFrame++;
        this._dispatchFrameChange();
        return true;
      }
      return false;
    }

    /**
     * Go back to previous frame
     * @returns {boolean} - True if moved, false if already at start
     */
    stepBackward() {
      if (this.currentFrame > 0) {
        this.currentFrame--;
        this._dispatchFrameChange();
        return true;
      }
      return false;
    }

    /**
     * Jump to specific frame by index
     * @param {number} index - Target frame index (0-based)
     * @returns {boolean} - True if moved, false if index out of range
     */
    jumpToFrame(index) {
      if (index >= 0 && index < this.frames.length) {
        this.currentFrame = index;
        this._dispatchFrameChange();
        return true;
      }
      return false;
    }

    /**
     * Get current frame object
     * @returns {Object|undefined} - Current frame data
     */
    getCurrentState() {
      return this.frames[this.currentFrame];
    }

    /**
     * Get playback progress information
     * @returns {Object} - { current, total, percent }
     */
    getProgress() {
      const total = this.frames.length;
      const current = this.currentFrame;
      // Prevent division by zero; if only 1 frame, progress is 0%
      const percent = total > 1
        ? (current / (total - 1)) * 100
        : 0;

      return {
        current,
        total,
        percent
      };
    }

    // ========== PLAYBACK METHODS ==========

    /**
     * Start automatic frame advancement
     */
    play() {
      // Don't start if already playing or no frames loaded
      if (this.isPlaying || this.frames.length === 0) {
        return;
      }

      // If at end, reset to beginning
      if (this.isAtEnd()) {
        this.currentFrame = 0;
        this._dispatchFrameChange();
      }

      this.isPlaying = true;
      this.timing.reset();
      this._animate(performance.now());
    }

    /**
     * Stop automatic frame advancement
     */
    pause() {
      this.isPlaying = false;
      if (this.rafId !== null) {
        cancelAnimationFrame(this.rafId);
        this.rafId = null;
      }
    }

    /**
     * Toggle between play and pause
     */
    togglePlayPause() {
      if (this.isPlaying) {
        this.pause();
      } else {
        this.play();
      }
    }

    /**
     * Stop playback and return to first frame
     */
    reset() {
      this.pause();
      this.currentFrame = 0;
      this._dispatchFrameChange();
    }

    /**
     * Check if at first frame
     * @returns {boolean}
     */
    isAtStart() {
      return this.currentFrame === 0;
    }

    /**
     * Check if at last frame
     * @returns {boolean}
     */
    isAtEnd() {
      return this.currentFrame >= this.frames.length - 1;
    }

    // ========== SPEED CONTROL ==========

    /**
     * Set playback speed
     * @param {number} multiplier - Speed multiplier (0.25x to 4x)
     * @returns {number} - Actual speed set (after clamping)
     */
    setSpeed(multiplier) {
      return this.timing.setSpeed(multiplier);
    }

    /**
     * Get current playback speed
     * @returns {number} - Speed multiplier
     */
    getSpeed() {
      return this.timing.speed;
    }

    /**
     * Get human-readable speed label
     * @returns {string} - Speed label like "1x", "2x"
     */
    getSpeedLabel() {
      return this.timing.getSpeedLabel();
    }

    // ========== PRIVATE METHODS ==========

    /**
     * RequestAnimationFrame loop for automatic playback
     * @param {number} currentTime - High-resolution timestamp
     */
    _animate(currentTime) {
      // Exit if playback stopped
      if (!this.isPlaying) {
        return;
      }

      // Check if enough time has passed for next frame
      if (this.timing.shouldAdvanceFrame(currentTime)) {
        const moved = this.stepForward();

        // If reached end, stop playback
        if (!moved && this.isAtEnd()) {
          this.pause();
          return;
        }
      }

      // Schedule next frame
      this.rafId = requestAnimationFrame((t) => this._animate(t));
    }

    /**
     * Dispatch frame change event and call callback
     */
    _dispatchFrameChange() {
      const detail = {
        frame: this.currentFrame,
        state: this.frames[this.currentFrame],
        totalFrames: this.frames.length,
        isPlaying: this.isPlaying
      };

      // Dispatch CustomEvent
      const event = new CustomEvent('cpu:framechange', { detail });
      window.dispatchEvent(event);

      // Call optional callback
      if (typeof this.onFrameChange === 'function') {
        this.onFrameChange(detail);
      }
    }
  }

  // Export to window
  window.AnimationEngine = AnimationEngine;
})();

/**
 * InstructionSet - RISC instruction definitions for CPU simulation
 *
 * Defines 8 core RISC instructions with their types, field mappings, and execute functions.
 * Instruction types: R (register), I (immediate), S (store), B (branch), J (jump)
 *
 * Instructions:
 * - ADD, SUB (R-type)
 * - ADDI, LW (I-type)
 * - SW (S-type)
 * - BEQ (B-type)
 * - J (J-type)
 * - NOP (special)
 */
(function() {
  'use strict';

  /**
   * Instruction definitions with execute functions
   * Execute functions compute results but do NOT mutate state
   */
  const INSTRUCTIONS = {
    ADD: {
      mnemonic: 'ADD',
      type: 'R',
      description: 'Add two registers',
      fields: {
        rs: true,   // Source register 1
        rt: true,   // Source register 2
        rd: true,   // Destination register
        immediate: false
      },
      execute: function(state, instruction) {
        const rsVal = state.getRegister(instruction.rs);
        const rtVal = state.getRegister(instruction.rt);
        const result = (rsVal + rtVal) >>> 0;  // 32-bit unsigned wrapping
        return {
          aluResult: result,
          writeReg: instruction.rd,
          writeData: result
        };
      }
    },

    SUB: {
      mnemonic: 'SUB',
      type: 'R',
      description: 'Subtract two registers',
      fields: {
        rs: true,
        rt: true,
        rd: true,
        immediate: false
      },
      execute: function(state, instruction) {
        const rsVal = state.getRegister(instruction.rs);
        const rtVal = state.getRegister(instruction.rt);
        const result = (rsVal - rtVal) >>> 0;  // 32-bit unsigned wrapping
        return {
          aluResult: result,
          writeReg: instruction.rd,
          writeData: result
        };
      }
    },

    ADDI: {
      mnemonic: 'ADDI',
      type: 'I',
      description: 'Add immediate to register',
      fields: {
        rs: true,
        rt: true,   // ADDI writes to rt (not rd) in MIPS
        rd: false,
        immediate: true
      },
      execute: function(state, instruction) {
        const rsVal = state.getRegister(instruction.rs);
        const result = (rsVal + instruction.immediate) >>> 0;  // 32-bit unsigned wrapping
        return {
          aluResult: result,
          writeReg: instruction.rt,
          writeData: result
        };
      }
    },

    LW: {
      mnemonic: 'LW',
      type: 'I',
      description: 'Load word from memory',
      fields: {
        rs: true,   // Base address register
        rt: true,   // Destination register
        rd: false,
        immediate: true  // Offset
      },
      execute: function(state, instruction) {
        const rsVal = state.getRegister(instruction.rs);
        const address = (rsVal + instruction.immediate) >>> 0;
        return {
          aluResult: address,
          writeReg: instruction.rt,
          memRead: true
        };
      }
    },

    SW: {
      mnemonic: 'SW',
      type: 'S',
      description: 'Store word to memory',
      fields: {
        rs: true,   // Base address register
        rt: true,   // Source data register
        rd: false,
        immediate: true  // Offset
      },
      execute: function(state, instruction) {
        const rsVal = state.getRegister(instruction.rs);
        const rtVal = state.getRegister(instruction.rt);
        const address = (rsVal + instruction.immediate) >>> 0;
        return {
          aluResult: address,
          writeData: rtVal,
          memWrite: true
        };
      }
    },

    BEQ: {
      mnemonic: 'BEQ',
      type: 'B',
      description: 'Branch if equal',
      fields: {
        rs: true,
        rt: true,
        rd: false,
        immediate: true  // Branch offset (in instructions, not bytes)
      },
      execute: function(state, instruction) {
        const rsVal = state.getRegister(instruction.rs);
        const rtVal = state.getRegister(instruction.rt);
        const zero = (rsVal === rtVal);
        const branchTarget = (state.pc + instruction.immediate * 4) >>> 0;
        return {
          zero: zero,
          branchTarget: branchTarget
        };
      }
    },

    J: {
      mnemonic: 'J',
      type: 'J',
      description: 'Jump to address',
      fields: {
        rs: false,
        rt: false,
        rd: false,
        immediate: true  // Jump target (word address)
      },
      execute: function(state, instruction) {
        const jumpTarget = (instruction.immediate * 4) >>> 0;
        return {
          jumpTarget: jumpTarget
        };
      }
    },

    NOP: {
      mnemonic: 'NOP',
      type: 'NOP',
      description: 'No operation',
      fields: {
        rs: false,
        rt: false,
        rd: false,
        immediate: false
      },
      execute: function(state, instruction) {
        return {};  // No effect
      }
    }
  };

  /**
   * InstructionSet class with helper methods
   */
  class InstructionSet {
    /**
     * Gets instruction definition by mnemonic
     * @param {string} mnemonic - Instruction mnemonic (e.g., 'ADD')
     * @returns {object|null} Instruction definition or null if not found
     */
    static get(mnemonic) {
      return INSTRUCTIONS[mnemonic.toUpperCase()] || null;
    }

    /**
     * Checks if instruction is a memory instruction
     * @param {string} mnemonic - Instruction mnemonic
     * @returns {boolean} True if LW or SW
     */
    static isMemoryInstruction(mnemonic) {
      const upper = mnemonic.toUpperCase();
      return upper === 'LW' || upper === 'SW';
    }

    /**
     * Checks if instruction is a branch/jump instruction
     * @param {string} mnemonic - Instruction mnemonic
     * @returns {boolean} True if BEQ or J
     */
    static isBranch(mnemonic) {
      const upper = mnemonic.toUpperCase();
      return upper === 'BEQ' || upper === 'J';
    }

    /**
     * Checks if instruction writes to a register
     * @param {string} mnemonic - Instruction mnemonic
     * @returns {boolean} True if instruction writes back to register file
     */
    static writesToRegister(mnemonic) {
      const upper = mnemonic.toUpperCase();
      // ADD, SUB, ADDI, LW write to registers
      // SW, BEQ, J, NOP do not
      return upper === 'ADD' || upper === 'SUB' || upper === 'ADDI' || upper === 'LW';
    }

    /**
     * Creates a concrete instruction object from mnemonic and field values
     * @param {string} mnemonic - Instruction mnemonic
     * @param {object} fields - Field values { rs, rt, rd, immediate }
     * @returns {object} Concrete instruction object
     */
    static createInstruction(mnemonic, fields = {}) {
      const def = InstructionSet.get(mnemonic);
      if (!def) {
        throw new Error(`Unknown instruction: ${mnemonic}`);
      }

      return {
        mnemonic: def.mnemonic,
        type: def.type,
        rs: fields.rs || 0,
        rt: fields.rt || 0,
        rd: fields.rd || 0,
        immediate: fields.immediate || 0
      };
    }

    /**
